def _make_datetime_field_compatible(self, field):
    if isinstance(field, datetime):
        if isinstance(field.tzinfo, tzlocal) and (not hasattr(field.tzinfo, '_hasdst')):
            return datetime(year=field.year, month=field.month, day=field.day, hour=field.hour, minute=field.minute, second=field.second, tzinfo=tzlocal())
    return field

def all_gather(self, tensor: torch.Tensor, mesh_dim: int=0) -> torch.Tensor:
    dim_group = self._dim_groups[mesh_dim]
    return all_gather(CommTensor(tensor.contiguous()), group=dim_group)

def fetch_metadata(self, url, progress_dialog=None):
    repo_handler = None
    for handler in BaseHandler.registry.values():
        handler_instance = handler(url)
        if handler_instance.can_handle():
            repo_handler = handler_instance
            break
    if repo_handler is None:
        raise Exception('No handler available for the given URL.')
    (status, description) = repo_handler.fetch_metadata(progress_dialog)
    return (status, description)

def __update(self):
    if self.__frame == self.__context.getFrame():
        return
    if self.__context.getFrame() not in self.__validFrames:
        raise ValueError('Invalid frame')
    self.clear()
    for plug in self.__variables.children():
        (value, name) = self.__variables.memberDataAndName(plug)
        if value is None:
            continue
        with IECore.IgnoredExceptions(Exception):
            value = value.value
        if isinstance(value, str):
            value = self.__context.substitute(value)
        self[name] = value
    self.__frame = self.__context.getFrame()

def command(self, command: AnyStr, site: Optional[SiteId]=None) -> None:
    command_str = _ensure_unicode(command).rstrip('\n')
    if not command_str.startswith('['):
        command_str = f'[{int(time.time())}] {command_str}'
    self.send_command(f'COMMAND {command_str}')

def _wait_for_task_token(self, env: Environment) -> None:
    callback_id = env.context_object_manager.context_object["Task"]["Token"]
    callback_endpoint = env.callback_pool_manager.get(callback_id)
    outcome = callback_endpoint.wait(timeout=30)
    if isinstance(outcome, CallbackOutcomeSuccess):
        outcome_output = json.loads(outcome.output)
        env.stack.append(outcome_output)
    elif isinstance(outcome, CallbackOutcomeFailure):
        raise CallbackOutcomeFailureError(callback_outcome_failure=outcome)
    else:
        raise NotImplementedError(f"Unsupported CallbackOutcome type '{type(outcome)}'.").

def get_user_tokens(self, bot, event, source, **rest):
    message_tokens = f'{source}, you have {source.tokens} tokens.'
    bot.send_message_to_user(source, message_tokens, event, method=self.settings['action_tokens'])
    if self.settings['action_tokens'] == 'say':
        bot.say(message_tokens)
    elif self.settings['action_tokens'] == 'whisper':
        bot.whisper(source, message_tokens)
    elif self.settings['action_tokens'] == 'me':
        bot.me(message_tokens)
    elif self.settings['action_tokens'] == 'reply':
        if event.type in ['action', 'pubmsg']:
            bot.say(message_tokens)
        elif event.type == 'whisper':
            bot.whisper(source, message_tokens)

def load_settings(path):
    os.sys.path.append(os.getcwd())

    def load_py_settings(path):
        config = {}
        execfile(path, {}, config)
        for key in config:
            setting = config[key]
            if isinstance(setting, dict) and key in settings:
                settings[key].update(setting)
            else:
                settings[key] = setting

    def load_yaml_settings(path):
        pass

    def load_json_settings(path):
        pass
    if path.endswith('.py'):
        load_py_settings(path)
    elif path.endswith('.json'):
        load_json_settings(path)
    else:
        load_yaml_settings(path)
    g.output_directory = os.path.abspath(settings.config.get('output'))
    g.static_directory = os.path.abspath(settings.config.get('static'))
    logging.info('Load Settings Finished')

def test_cholesky(self):

    def func(root, upper):
        x = 0.5 * (root + root.transpose(-1, -2).conj())
        return torch.cholesky(x, upper)

    def run_test(upper, dims, dtype):
        root = torch.rand(*dims, dtype=dtype, requires_grad=True)
        root = root + torch.eye(dims[-1])
        gradcheck(func, [root, upper])
        if not dtype.is_complex:
            gradgradcheck(func, [root, upper])
        root = torch.rand(*dims, dtype=dtype)
        root = torch.matmul(root, root.transpose(-1, -2).conj())
        root.requires_grad_()
        chol = root.cholesky().sum().backward()
        self.assertEqual(root.grad, root.grad.transpose(-1, -2).conj())
    for (upper, dims, dtype) in product([True, False], [(3, 3), (4, 3, 2, 2)], [torch.double, torch.cdouble]):
        run_test(upper, dims, dtype)

def init_asic_vlan_info(self, vlan_name):
    if vlan_name[0:4] != 'Vlan' or not vlan_name[4:].isnumeric():
        self.ret_temp['ASIC_DB']['tables_not_found'] = ['ASIC_STATE:SAI_OBJECT_TYPE_VLAN']
        return ({}, {})
    vlan_num = int(vlan_name[4:])
    req = MatchRequest(db='ASIC_DB', table='ASIC_STATE:SAI_OBJECT_TYPE_VLAN', key_pattern='*', field='SAI_VLAN_ATTR_VLAN_ID', value=str(vlan_num), ns=self.ns)
    ret = self.match_engine.fetch(req)
    self.add_to_ret_template(req.table, req.db, ret['keys'], ret['error'])

